(* [comment removed for export] *)
Definition saves (E : Z) (R : bvmap 5 word) (M : mem) : Prop :=
  L5.u64_at RSEGS M (E - 8) (bvu (getr R (reg 1))) /\ L5.u64_at RSEGS M (E - 16) (bvu (getr R (reg 8)))
  /\ L5.u64_at RSEGS M (E - 24) (bvu (getr R (reg 9))) /\ L5.u64_at RSEGS M (E - 32) (bvu (getr R (reg 18)))
  /\ L5.u64_at RSEGS M (E - 40) (bvu (getr R (reg 19))) /\ L5.u64_at RSEGS M (E - 48) (bvu (getr R (reg 20)))
  /\ L5.u64_at RSEGS M (E - 56) (bvu (getr R (reg 21))) /\ L5.u64_at RSEGS M (E - 64) (bvu (getr R (reg 22)))
  /\ L5.u64_at RSEGS M (E - 72) (bvu (getr R (reg 23))) /\ L5.u64_at RSEGS M (E - 80) (bvu (getr R (reg 24)))
  /\ L5.u64_at RSEGS M (E - 88) (bvu (getr R (reg 25))) /\ L5.u64_at RSEGS M (E - 96) (bvu (getr R (reg 26)))
  /\ L5.u64_at RSEGS M (E - 104) (bvu (getr R (reg 27))).
Definition own1 (E V2 fb : Z) (R : bvmap 5 word) (M : mem) : Prop :=
  saves E R M /\ L5.u64_at RSEGS M (V2 - 144) (fb + 592) /\ L5.u64_at RSEGS M (V2 - 136) (fb + 992).
(* [comment removed for export] *)
Definition own2 (E V2 fb F : Z) (R : bvmap 5 word) (M : mem) : Prop :=
  own1 E V2 fb R M
  /\ L5.u64_at RSEGS M (V2 - 224) (F + 32) /\ L5.u64_at RSEGS M (V2 - 192) (Sh (fb + 992)) /\ L5.u64_at RSEGS M (V2 - 184) (Sh (fb + 592 + 376))
  /\ L5.u64_at RSEGS M (V2 - 176) F /\ L5.u64_at RSEGS M (V2 - 168) F /\ L5.u64_at RSEGS M (V2 - 160) (fb + 592 + 376) /\ L5.u64_at RSEGS M (V2 - 152) (Sh (fb + 1232))
  /\ L5.u64_at RSEGS M (V2 - 112) F.
Definition ocell1 (E V2 : Z) (a : Z) : Prop := E - 104 <= a < E \/ V2 - 144 <= a < V2 - 128.
Definition ocell2 (E V2 : Z) (a : Z) : Prop := E - 104 <= a < E \/ V2 - 224 <= a < V2 - 104.
Lemma saves_agree E R M1 M1' : 0 <= E - 104 -> E <= 2 ^ 64 ->
  saves E R M1 -> (forall a, E - 104 <= a < E -> M1' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> saves E R M1'.
