Section Frame.
Variables (F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Local Notation OWN := (own2 sp V2 fb F R).
Local Notation OC := (ocell2 sp V2).
Hypothesis G : PQAKUF.gctx L ar HIk D0 LBX FF LK Aw sp (PMSPA.pm_scr 11) spc spc sp OC OWN F fl 1 LK2 M2 model2 cr (mown s sa).
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (mown s sa ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes 1 <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes 1 / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
(* [comment removed for export] *)
Local Notation MM := (PQALPK.lp_mem L ar HIk D0 M model LBX FF LK Aw sp fb cat s str sm e false spc OWN F).
Local Notation LPC := (PQALPK.lpc L cr (PNRNA.pot_runA L ar s sa) TSRESA).

(* [comment removed for export] *)
Definition REGS (Rx : bvmap 5 word) : Prop :=
  getr Rx (reg 2) = Z_to_bv 64 spc /\ getr Rx (reg 8) = Z_to_bv 64 sp /\ getr Rx (reg 9) = Z_to_bv 64 spc /\ getr Rx (reg 18) = Z_to_bv 64 0x2384c
  /\ getr Rx (reg 19) = Z_to_bv 64 oec /\ getr Rx (reg 20) = Z_to_bv 64 (Sh (fb + 592 + 384)) /\ getr Rx (reg 21) = Z_to_bv 64 (Sh (fb + 592 + 8)) /\ getr Rx (reg 22) = Z_to_bv 64 2147450880
  /\ getr Rx (reg 23) = Z_to_bv 64 (fb + 592 + 9) /\ getr Rx (reg 24) = Z_to_bv 64 (fb + 592 + 8) /\ getr Rx (reg 25) = Z_to_bv 64 (fb + 592 + 384) /\ getr Rx (reg 26) = Z_to_bv 64 (Sh (fb + 592 + 9))
  /\ getr Rx (reg 27) = Z_to_bv 64 (Sh F)
  /\ (forall j, In j [3; 4]%nat -> getr Rx (reg j) = getr R (reg j)).

Ltac kitp lem H := pose proof (lem L ar C IL LR HIk D0 tsp TSRESA LY FAMok ICokF ILY TSPB K R M model LBX FF LK Aw cr sp r fb cat n s sa str sm e false HH AM K0 ENT FRM FRS FOK RPRE INCS KONT
                              spc OC OWN F fl LK2 M2 model2 G APART HSPC HOC16) as H.

