Ltac fdP P := L5SAR.feed P ltac:(first [assumption | unfold PQALPP1.aligned, PQALPP2.aligned, PQALPP3.aligned, PQALPP4.aligned; assumption | apply PQALPK.bvu_rng
                                       | unfold PQALPP1.aligned, PQALPP2.aligned, PQALPP3.aligned, PQALPP4.aligned; lia | lia]).
(* [comment removed for export] *)
Ltac ro_subst FR := lazymatch type of FR with (forall a : bv 64, ?M' a = ?M a) =>
  let E := fresh in assert (E : M' = M) by (apply functional_extensionality; exact FR); subst M'; clear FR end.

(* [comment removed for export] *)
Lemma shape_top stk : PQRA.mstack_shape stk ->
  exists pre top, stk = pre ++ [top] /\ PQMA.mstate_ok top
    /\ ((pre = [] /\ PQMA.mode_bottom (PQMA.ms_mode top)) \/ (pre <> [] /\ PQMA.mode_cont (PQMA.ms_mode top) /\ PQRA.mstack_shape pre)).
Proof.
