Lemma shape_set_last pre top top' : PQRA.mstack_shape (pre ++ [top]) -> PQMA.mstate_ok top' ->
  (pre = [] -> PQMA.mode_bottom (PQMA.ms_mode top')) -> (pre <> [] -> PQMA.mode_cont (PQMA.ms_mode top')) ->
