(* [comment removed for export] *)
Definition AH (R1 : bvmap 5 word) (RC : list Z) (Dc : list (list Z)) (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z))
           (s1 : PQMA.mpst) (sa1 : NEMA.aest) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) : Prop :=
  (exists b1, MM RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 /\ (b1 = false -> NEMA.bal sa1)) /\ REGS R1 /\ PQMA.cpl s1 (NEMA.ae_a sa1) /\ PQMA.acct n s1 (NEMA.ae_a sa1) sm1
  /\ NEMA.oacct n s1 sa1 sm1 /\ NEMA.ebound sa1 /\ PQRA.minv_d 0 s1 /\ PQRA.bb_room s1 sm1
  /\ LPC cr1 (PNRNA.pot_runA L ar s1 sa1) (tsp Dc RC).
(* [comment removed for export] *)
Definition HEADK (mu : Z) : Prop :=
  forall (fx1 : FPState) R1 RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1,
    AH R1 RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 -> PQRA.mmu s1 sm1 < mu -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0xcffd0 M1 model1) K.

(* [comment removed for export] *)
Lemma TAILQ mu (fx2 : FPState) R2 RC D3 M3 model3 LK3 Aw3 (s2 s3 : PQMA.mpst) (sa2 sa3 : NEMA.aest) (sm2 sm3 : PM.strm) e3 cr3 b3 (ra : Z) (Rx : bvmap 5 word) (Mx : mem) :
  HEADK mu -> (ra = 0xd0040 \/ ra = 0xd0078 \/ ra = 0xd00e4 \/ ra = 0xd0160) -> REGS R2 ->
  MM RC D3 M3 model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 b3 ->
  ((b3 = true)
   \/ (b3 = false /\ PQMA.cpl s3 (NEMA.ae_a sa3) /\ PQMA.acct n s3 (NEMA.ae_a sa3) sm3 /\ NEMA.oacct n s3 sa3 sm3 /\ NEMA.ebound sa3 /\ NEMA.bal sa3
       /\ PQRA.minv_d 0 s3 /\ PNRNA.mprog_item Rx Mx s2 s3 sa2 sa3 sm2 sm3 /\ PQRA.room_keep s2 s3 sm2 sm3)) ->
  PQRA.bb_room s2 sm2 -> LPC cr3 (PNRNA.pot_runA L ar s3 sa3) (tsp D3 RC) -> PQRA.mmu s2 sm2 <= mu ->
