(* [comment removed for export] *)
Lemma obj_more RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 :
  MM RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  L5.u8_at RSEGS MV (fb + 592 + 16) 0 /\ L5.u64_at RSEGS MV (fb + 592 + 376) (PQMA.p_sb s1)
