  HEADK mu -> 4096 * PM.unread (PQMA.p_src s1) sm1 + 2 * Z.of_nat (length pre) < mu ->
  REGS Rsv -> REGSE Rsv R3 ->
  L5.u64_at RSEGS M4 (V2 - 232) 0xd0214 -> L5.u64_at RSEGS M4 (V2 - 240) (bvu (getr Rsv (reg 8))) -> L5.u64_at RSEGS M4 (V2 - 248) (bvu (getr Rsv (reg 9))) ->
