  PQMA.p_done s1 = 0 -> PQMA.p_depth s1 = Z.of_nat (length pre) - 1 -> PQRA.mstack_shape pre ->
  length (PQMA.a_lv (NEMA.ae_a sa4)) = length pre -> PQMA.acct n (PQALPK.set_stk s1 pre) (NEMA.ae_a sa4) sm1 -> NEMA.oacct n (PQALPK.set_stk s1 pre) sa4 sm1 -> NEMA.ebound sa4 -> PQRA.bb_room s1 sm1 ->
